-- Experiment 8: one-time fix so MySQL generates student IDs.
--
-- Hibernate's ddl-auto=update never alters an existing primary key, so a students
-- table created in Exp 4 (when IDs were sent by the client) has no AUTO_INCREMENT.
-- Run this once, only if `DESCRIBE students;` does NOT show auto_increment under Extra.
--
--   mysql -u root -p < docs/sql/exp8_enable_auto_increment.sql
--
-- The foreign key on course.student_id must be dropped first because MySQL won't
-- modify a column that is referenced by a foreign key. Its name is generated by
-- Hibernate, so this script looks it up instead of hard-coding it.

USE java_spring;

SET @fk := (
    SELECT CONSTRAINT_NAME
    FROM information_schema.KEY_COLUMN_USAGE
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'course'
      AND COLUMN_NAME = 'student_id'
      AND REFERENCED_TABLE_NAME = 'students'
    LIMIT 1
);

-- 1. Drop the foreign key (skipped if none exists)
SET @sql := IF(@fk IS NULL, 'SELECT ''no foreign key to drop''',
               CONCAT('ALTER TABLE course DROP FOREIGN KEY ', @fk));
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2. Make students.id auto-increment
ALTER TABLE students MODIFY COLUMN id INT NOT NULL AUTO_INCREMENT;

-- 3. Restore the foreign key under the same name
SET @sql := IF(@fk IS NULL, 'SELECT ''no foreign key to restore''',
               CONCAT('ALTER TABLE course ADD CONSTRAINT ', @fk,
                      ' FOREIGN KEY (student_id) REFERENCES students(id)'));
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 4. Verify: id should show auto_increment, course should still have student_id
DESCRIBE students;
DESCRIBE course;
